html:
{%- set d = get_aod_data(doc.name) -%}
{%- macro qint(v) -%}{{ '{:,}'.format((v or 0)|int) }}{%- endmacro -%}

<style>
  .aod { font-family: Arial, Helvetica, sans-serif; font-size: 11.5px; color:#000; }
  .aod-title { text-align:center; font-weight:bold; font-size:13px; text-decoration:underline; margin-bottom:10px; }
  .aod-hdr { width:100%; border-collapse:collapse; margin-bottom:10px; }
  .aod-hdr > tbody > tr > td { vertical-align:top; }
  .aod-hdr .r { width:38%; }
  .aod-hdr .r table { border-collapse:collapse; }
  .aod-hdr .r td { padding:1px 3px; font-size:11.5px; white-space:nowrap; }
  .aod-hdr .r td:first-child { font-weight:bold; }
  .it { width:100%; border-collapse:collapse; }
  .it th { border:1px solid #000; padding:4px 6px; font-size:11.5px; background:#fff; }
  .it th.q, .it td.q { width:90px; text-align:right; }
  .it td { border:1px solid #000; padding:4px 6px; vertical-align:top; font-size:11px; }
  .it td.desc div { line-height:1.35; }
  .it .bd { margin-top:3px; }
  .it tr.total td { font-weight:bold; }
  .ft { margin-top:10px; font-size:11.5px; }
  .ft .ln { margin:2px 0; }
  .sign { width:100%; border-collapse:collapse; margin-top:34px; }
  .sign td { width:50%; text-align:center; font-size:11.5px; padding-top:2px; border-top:1px dotted #000; }
  .disc { margin-top:14px; font-size:10px; }
</style>

<div class="aod">

  <div class="aod-title">Delivery Advice</div>

  <table class="aod-hdr">
    <tr>
      <td class="l">
        <div><b>{{ d.customer }}</b></div>
        {%- for ln in d.address_lines %}
        <div>{{ ln }}{% if not loop.last %},{% endif %}</div>
        {%- endfor %}
      </td>
      <td class="r">
        <table>
          <tr><td>AOD No</td><td>: {{ d.aod_no }}</td></tr>
          <tr><td>PO No</td><td>: {{ d.po_no }}</td></tr>
          <tr><td>Date</td><td>: {{ d.date }}</td></tr>
          <tr><td>Job No</td><td>: {{ d.job_no }}</td></tr>
        </table>
      </td>
    </tr>
  </table>

  <table class="it">
    <thead>
      <tr><th class="desc">Description</th><th class="q">Quantity</th></tr>
    </thead>
    <tbody>
      {%- for p in d.packings %}
      <tr>
        <td class="desc">
          <div>{{ p.item_name }}</div>
          <div>Item code: {{ p.item or '' }}</div>
          {%- if p.breakdown %}<div class="bd">{{ p.breakdown }}</div>{%- endif %}
          {%- if p.extra %}<div>Extra: {{ p.extra|int }}</div>{%- endif %}
        </td>
        <td class="q">{{ qint(p.packed_qty) }}</td>
      </tr>
      {%- endfor %}
      <tr class="total">
        <td class="desc">Total</td>
        <td class="q">{{ qint(d.total_qty) }}</td>
      </tr>
    </tbody>
  </table>

  <div class="ft">
    <div class="ln">Remarks: {{ doc.get('remarks') or '' }}</div>
    <div class="ln">Driver: {{ doc.get('driver_name') or ""}}</div>
    <div class="ln">Vehicle: {{ doc.get('vehicle_no') or ""}}</div>
  </div>

  <table class="sign">
    <tr>
      <td>For Savinda Graphic Systems (Pvt) Ltd.</td>
      <td>Received By</td>
    </tr>
  </table>

  <div class="disc">
    Any quality or quantity concerns must be reported to Savinda Graphic Systems (Pvt) Ltd within 2 weeks from the date of release
  </div>

</div>
